import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAudio } from '../contexts/AudioContext';
import AudioControl from '../components/ui/AudioControl';
import '../styles/pages/LandingPage.css';

const LandingPage: React.FC = () => {
  const { isPlaying, playLandingMusic } = useAudio();
  const [hasInteracted, setHasInteracted] = useState(false);
  const [showPlayButton, setShowPlayButton] = useState(false);
  
  // Intentar reproducir la música cuando se cargue la página
  useEffect(() => {
    const attemptAutoplay = async () => {
      if (!isPlaying) {
        try {
          const success = await playLandingMusic();
          // Si no se puede reproducir automáticamente, mostrar un botón para iniciar manualmente
          if (!success) {
            setShowPlayButton(true);
          }
        } catch (error) {
          console.error("Error al intentar reproducir música automáticamente:", error);
          setShowPlayButton(true);
        }
      }
    };
    
    attemptAutoplay();
  }, [isPlaying, playLandingMusic]);
  
  // Maneja la interacción del usuario
  const handleUserInteraction = async () => {
    if (!hasInteracted) {
      setHasInteracted(true);
      await playLandingMusic();
      setShowPlayButton(false);
    }
  };

  return (
    <div 
      className="landing-page"
      onClick={showPlayButton ? handleUserInteraction : undefined}
    >
      <div className="landing-content">
        <div className="title-container">
          <h1 className="game-title">Heroes&Hostias</h1>
        </div>
        
        <div className="buttons-container">
          <Link to="/login" className="landing-button login-button">
            <span className="button-text">Iniciar Sesión</span>
          </Link>
          
          <Link to="/register" className="landing-button register-button">
            <span className="button-text">Registrarse</span>
          </Link>
        </div>
      </div>
      
      {showPlayButton && (
        <div className="music-prompt">
          <button 
            className="play-music-button"
            onClick={handleUserInteraction}
          >
            ▶ Activar Música
          </button>
        </div>
      )}
      
      <div className="audio-controls-landing">
        <AudioControl variant="small" showLabel={true} />
      </div>
      
      <div className="version-footer">
        <span>v1.0.0 Beta</span>
      </div>
    </div>
  );
};

export default LandingPage;
